                            "cache_streams": True,
                        }
                    },
                }
            ),
            encoding="utf-8",
        )
        state = tmp_path / ".zerorun"
        state.mkdir()
        (state / "events.jsonl").write_text(
            json.dumps(
                {
                    "status": "HIT_REUSED",
                    "wall_ms": 25,
                    "execution_ms": 1025,
                    "saved_ms": 1000,
                }
            )
            + "\n",
            encoding="utf-8",
        )
    
        response = mcp.handle_request(
            {
                "jsonrpc": "2.0",
                "id": 3,
                "method": "tools/call",
                "params": {"name": "stats", "arguments": {"root": str(tmp_path)}},
            }
        )
        payload = response["result"]["structuredContent"]
